const updateCheckoutAttempt = `-- name: UpdateCheckoutAttempt :execrows
UPDATE billing.checkout_attempts SET
    customer_id = $2,
    price_id = $3,
    mode = $4,
    rail = $5,
    status = $6,
    amount = $7,
    currency = $8,
    expires_at = $9,
    reference = $10,
    transaction_id = $11,
    payment_id = $12,
    subscription_id = $13,
    metadata = $14,
    rail_fields = $15,
    rail_state = COALESCE($16::jsonb, '{}'::jsonb)
      || CASE WHEN rail_state ? '_openrails_request_fingerprint' THEN jsonb_build_object('_openrails_request_fingerprint', rail_state->'_openrails_request_fingerprint') ELSE '{}'::jsonb END
      || CASE WHEN rail_state ? 'accepted_purchase' THEN jsonb_build_object('accepted_purchase', rail_state->'accepted_purchase') ELSE '{}'::jsonb END
      || CASE WHEN rail_state->>'purchase_submitted'='true' THEN '{"purchase_submitted":true}'::jsonb ELSE '{}'::jsonb END
      || CASE WHEN rail_state->>'provider_closed'='true' THEN '{"provider_closed":true}'::jsonb ELSE '{}'::jsonb END,
    psp_id = $17::uuid,
    updated_at = $18
WHERE checkout_attempts.merchant_id = $19::uuid AND id = $1
  AND deleted_at IS NULL
  AND (NOT COALESCE(rail_state ? 'accepted_purchase', false)
       OR status <> 'succeeded' OR $6 = 'succeeded')
  AND (NOT COALESCE(rail_state ? 'accepted_purchase', false)
       OR (customer_id=$2 AND price_id IS NOT DISTINCT FROM $3 AND mode=$4 AND rail=$5
           AND amount IS NOT DISTINCT FROM $7 AND currency IS NOT DISTINCT FROM $8
           AND psp_id=$17::uuid))
  AND (NOT COALESCE((rail_state->>'provider_closed')::boolean, false)
       OR COALESCE(($16::jsonb->>'provider_closed')::boolean, false))
`

type UpdateCheckoutAttemptParams struct {
	ID             uuid.UUID
	CustomerID     uuid.UUID
	PriceID        *uuid.UUID
	Mode           string
	Rail           string
	Status         string
	Amount         *int64
	Currency       *string
	ExpiresAt      *time.Time
	Reference      *string
	TransactionID  *string
	PaymentID      *uuid.UUID
	SubscriptionID *uuid.UUID
	Metadata       []byte
	RailFields     []byte
	RailState      []byte
	PspID          uuid.UUID
	UpdatedAt      time.Time
	MerchantID     uuid.UUID
}

func (q *Queries) UpdateCheckoutAttempt(ctx context.Context, arg UpdateCheckoutAttemptParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateCheckoutAttempt,
		arg.ID,
		arg.CustomerID,
		arg.PriceID,
		arg.Mode,
		arg.Rail,
		arg.Status,
		arg.Amount,
		arg.Currency,
		arg.ExpiresAt,
		arg.Reference,
		arg.TransactionID,
		arg.PaymentID,
		arg.SubscriptionID,
		arg.Metadata,
		arg.RailFields,
		arg.RailState,
		arg.PspID,
		arg.UpdatedAt,
		arg.MerchantID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
